#!/usr/bin/env node
// Writes every tool's manifest from one place: the version and description
// below, and skills/blind-spots/SKILL.md for the review itself.
//
//   node scripts/build.mjs          write every generated file
//   node scripts/build.mjs --check  fail if any generated file is out of date
//
// Edit SKILL.md or the constants here, never the generated files.

import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs'
import { dirname, join, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..')
const VERSION = '0.5.0'
const NAME = 'blind-spots'
const DISPLAY = 'Blind spots'
const REPO = 'https://github.com/aadityasp/blind-spots'
const AUTHOR = { name: 'Aditya Appana', url: 'https://github.com/aadityasp' }
const SHORT = 'See what your AI assistant decided without asking you, rated by risk.'
const LONG =
  'See what your AI assistant decided without asking you, rated by risk. Say "blind spots" to get the one decision most worth checking, the rest rated by what a wrong guess would cost, and the questions you have not raised yet. Say "blind spots on" to get it after every reply.'
const KEYWORDS = ['assumptions', 'blind-spots', 'review', 'planning', 'risk', 'skills']
const SKILL_PATH = 'skills/blind-spots/SKILL.md'

const skill = readFileSync(join(ROOT, SKILL_PATH), 'utf8')
const body = skill.replace(/^---\n[\s\S]*?\n---\n/, '').trim()
const json = value => JSON.stringify(value, null, 2) + '\n'

// The Claude Code plugin keeps its own longer description: it draws a live pane.
const claudePlugin = JSON.parse(readFileSync(join(ROOT, '.claude-plugin/plugin.json'), 'utf8'))

const files = {
  '.claude-plugin/plugin.json': json({ ...claudePlugin, version: VERSION }),

  // Gemini CLI: `gemini extensions install <repo>`. The context file loads the
  // skill so "blind spots on" works, and the command gives /blind-spots.
  'gemini-extension.json': json({ name: NAME, description: SHORT, version: VERSION, contextFileName: 'GEMINI.md' }),
  'GEMINI.md': `@./${SKILL_PATH}\n`,
  'commands/blind-spots.toml': `# Generated by scripts/build.mjs from ${SKILL_PATH}. Do not edit.
description = "${SHORT}"
prompt = """
Run Blind spots now, following these instructions exactly.

${body.replace(/"""/g, '\\"\\"\\"')}

{{args}}
"""
`,

  // Any chat with no way to install anything: paste the review in.
  'PROMPT.md': `# Blind spots, as a prompt

<!-- Generated by scripts/build.mjs from ${SKILL_PATH}. Do not edit. -->

For an AI chat where nothing can be installed. If your tool can install a skill, plugin or extension, use the [install table](README.md#install) instead. Then you just say "blind spots".

Paste everything below the line into the chat after the assistant has done some work. To get it after every reply, say "blind spots on" afterwards.

---

${body}
`,

  // Google Antigravity: `agy plugin install <repo>`.
  '.antigravity-plugin/plugin.json': json({
    name: NAME,
    displayName: DISPLAY,
    version: VERSION,
    description: SHORT,
    suggestedPrompts: ['blind spots', 'blind spots on'],
    category: 'Developer Tools',
    keywords: KEYWORDS,
    author: AUTHOR,
    homepage: REPO,
    repository: REPO,
    license: 'MIT',
  }),

  // Agent Plugins format at the root: GitHub Copilot CLI
  // (`copilot plugin install aadityasp/blind-spots`), and read by Antigravity,
  // Kiro and Codex too. Only `name` is required.
  'plugin.json': json({
    name: NAME,
    version: VERSION,
    description: SHORT,
    author: AUTHOR,
    homepage: REPO,
    repository: REPO,
    license: 'MIT',
    keywords: KEYWORDS,
    skills: './skills/',
  }),

  // Cursor: Customize, then "From GitHub Repository", reads this marketplace.
  '.cursor-plugin/marketplace.json': json({
    name: NAME,
    owner: AUTHOR,
    plugins: [{ name: NAME, description: SHORT, version: VERSION, source: './' }],
  }),
  '.cursor-plugin/plugin.json': json({
    name: NAME,
    displayName: DISPLAY,
    description: SHORT,
    version: VERSION,
    author: AUTHOR,
    homepage: REPO,
    repository: REPO,
    license: 'MIT',
    keywords: KEYWORDS,
    skills: './skills/',
  }),

  // OpenAI Codex: the plugin, and a marketplace so the repo can be added.
  '.codex-plugin/plugin.json': json({
    name: NAME,
    version: VERSION,
    description: SHORT,
    author: AUTHOR,
    homepage: REPO,
    repository: REPO,
    license: 'MIT',
    keywords: KEYWORDS,
    skills: './skills/',
    interface: {
      displayName: DISPLAY,
      shortDescription: SHORT,
      longDescription: LONG,
      developerName: AUTHOR.name,
      category: 'Developer Tools',
      capabilities: ['Interactive'],
      defaultPrompt: ['blind spots', 'blind spots on'],
      websiteURL: REPO,
    },
  }),
  '.agents/plugins/marketplace.json': json({
    name: NAME,
    interface: { displayName: DISPLAY },
    plugins: [
      {
        name: NAME,
        source: { source: 'url', url: './' },
        policy: { installation: 'AVAILABLE', authentication: 'ON_INSTALL' },
        category: 'Developer Tools',
      },
    ],
  }),

  // Kimi Code: `/plugins install <repo>`.
  '.kimi-plugin/plugin.json': json({
    name: NAME,
    version: VERSION,
    description: SHORT,
    author: AUTHOR,
    homepage: REPO,
    license: 'MIT',
    keywords: KEYWORDS,
    skills: './skills/',
  }),

  // Devin CLI: `devin plugins install aadityasp/blind-spots`.
  '.devin-plugin/plugin.json': json({
    name: NAME,
    version: VERSION,
    description: SHORT,
    author: AUTHOR,
    homepage: REPO,
    repository: REPO,
    license: 'MIT',
    keywords: KEYWORDS,
  }),

  // Muse: `muse plugins install ./blind-spots`.
  '.muse-plugin/plugin.json': json({
    schemaVersion: 1,
    name: NAME,
    displayName: DISPLAY,
    version: VERSION,
    description: SHORT,
    compat: { source: 'native', manifestDir: '.muse-plugin' },
    capabilities: {
      skills: [{ id: NAME, path: SKILL_PATH }],
      commands: [],
      hooks: [],
      mcpServers: [],
      reminders: [],
    },
  }),

  // Hermes Agent: `hermes plugins install aadityasp/blind-spots --enable`.
  '.hermes-plugin/plugin.yaml': `name: ${NAME}\nversion: ${VERSION}\ndescription: ${SHORT}\nauthor: aadityasp\n`,

  // Pi: `pi install git:github.com/aadityasp/blind-spots`.
  'package.json': json({
    name: NAME,
    version: VERSION,
    private: true,
    description: SHORT,
    license: 'MIT',
    repository: REPO,
    keywords: ['pi-package', ...KEYWORDS],
    pi: { skills: ['./skills'] },
  }),
}

const isCheck = process.argv.includes('--check')
const stale = []

for (const [path, content] of Object.entries(files)) {
  const full = join(ROOT, path)
  const current = existsSync(full) ? readFileSync(full, 'utf8') : undefined
  if (current === content) continue
  if (isCheck) {
    stale.push(path)
    continue
  }
  mkdirSync(dirname(full), { recursive: true })
  writeFileSync(full, content)
  console.log(`wrote ${path}`)
}

if (isCheck && stale.length > 0) {
  console.error(`Out of date: ${stale.join(', ')}. Run node scripts/build.mjs.`)
  process.exit(1)
}
if (isCheck) console.log(`All ${Object.keys(files).length} generated files are up to date (v${VERSION}).`)
